-- Which walkability grid a plan floor has, and legs through it, for the route tool's "Snap to corridors".
-- Data/WalkData.lua holds the grids (generated by tools/walk_grids.py), Model/Walk.lua finds the paths.
--
-- A floor's grid is the one of the picture its plan coordinates are measured on, whatever the map draws right now:
--   1. the old dungeon map tiles of a classic floor ("t:<tile name>"; plan space is the picture's);
--   2. Santiago Reyes' map of a Forever floor ("r:<file>"; the Dungeon Journal and Forever Dungeon Routes addons draw
--      the same pictures), through the alignment the map would be drawn with (Data/ReyesMaps.lua);
--   3. the game's minimap pictures ("m:<instance>:<floor>"), through that floor's own transform (Data/MinimapArt.lua).
-- Without one (open outdoor maps, floors without art) legs stay straight.
--
-- Corridors.Leg finds a leg in the call (Walk.Path run to completion, at most Walk.MAX_NODES cells). What a floor needs
-- once, decoding its grid and the wall distances and prices of Walk.Prices, is prepared ahead: Corridors.Prepare starts
-- it when the route tool is chosen on a floor with a grid and when the map changes floor with that tool
-- (UI/Panels/MapControls.lua), one piece a frame (the decoding, then the three passes of Walk.Prices; C_Timer.After(0)).
-- A leg asked for before that is done finishes it in the same call. Preparing reads only Data/WalkData.lua, never a
-- plan; nothing runs while no floor is being prepared. The grids are dropped (Corridors.Reset) when the map hides or
-- the tool leaves Route (UI/Panels/MapControls.lua). docs/DATA-SOURCES.md has the measured times
-- (tools/walk_timing.lua).

local _, ns = ...
local Corridors = ns:NewModule("Corridors")
local Walk = ns.Walk

-- Decoded grids kept, most recently used first. A prepared 120 x 80 grid (its cells, prices and the search's arrays)
-- takes about 1.6 MB in reference Lua 5.1, so the cache holds at most about 6.5 MB, and only while the route tool is on.
Corridors.CACHE = 4

local cache = {} -- { { key, grid } }, most recently used first
local job = nil -- the floor being prepared: { key, run = coroutine }
local scheduled = false -- a step is waiting for the next frame
local stats = { legs = 0, steps = 0, maxExpanded = 0 }
Corridors.stats = stats

-- The grid key of floor `index` as the map shows it (Floors.View: the plan's floors, then the instance's art floors
-- none of them stands for) and its plan -> grid alignment (nil: the same space), or nil. The art is the one at the
-- floor's `art` position when it has one, else at its own position, as the map draws it.
function Corridors.KeyFor(plan, index)
	local view = type(plan) == "table" and ns.Floors.View(plan)
	local floor = view and type(view.floors) == "table" and view.floors[index]
	if type(floor) ~= "table" or ns.Floors.IsOutside(floor) then
		return nil
	end
	local data = ns.WalkData or {}
	local name = plan.instance and ns.Instances.CanonicalName(plan)
	local pos = floor.art or index
	local tiles = ns.GameFiles.MapTiles(name)
	if tiles and tiles[pos] then
		local key = "t:" .. tiles[pos]
		return data[key] and key or nil, nil
	end
	local f = ns.ReyesMaps.Pick(view, index)
	if f then
		local key = "r:" .. f.file
		if not data[key] then
			return nil
		end
		local art = ns.ReyesMaps.FloorArt(view, index)
		local align = art and art.align
		return key, align and align.mode == "fit" and align or nil
	end
	local k = ns.GameFiles.Key(name or "")
	local key = k and ("m:" .. k .. ":" .. pos)
	if key and data[key] then
		local art = ns.MinimapArt.FloorArt(view, index)
		return key, art and art.align or nil
	end
	return nil
end

-- Does plan floor `index` have a grid?
function Corridors.Has(plan, index)
	return Corridors.KeyFor(plan, index) ~= nil
end

-- The cached grid of a key (now the most recently used), or nil.
local function cached(key)
	for i, e in ipairs(cache) do
		if e[1] == key then
			table.remove(cache, i)
			table.insert(cache, 1, e)
			return e[2]
		end
	end
	return nil
end

-- The decoded grid of a key (cached), or nil.
function Corridors.Grid(key)
	local grid = cached(key)
	if grid then
		return grid
	end
	local d = ns.WalkData and ns.WalkData[key]
	grid = type(d) == "table" and Walk.Decode(d[1], d[2], d[3]) or nil
	if grid then
		table.insert(cache, 1, { key, grid })
		cache[Corridors.CACHE + 1] = nil
	end
	return grid
end

-- One piece of the preparation a frame, while there is one.
local function step()
	scheduled = false
	local j = job
	if not j then
		return
	end
	stats.steps = stats.steps + 1
	local ok, err = coroutine.resume(j.run)
	if not ok then
		ns:Debug("corridors: " .. tostring(err))
	end
	if not ok or coroutine.status(j.run) == "dead" then
		job = nil
		return
	end
	scheduled = true
	C_Timer.After(0, step)
end

-- Starts preparing plan floor `index` over the next frames, unless it has no grid or is prepared or being prepared.
-- Preparing another floor drops the one in progress (its work is redone when that floor is asked for again).
function Corridors.Prepare(plan, index)
	local key = Corridors.KeyFor(plan, index)
	if not key or (job and job.key == key) then
		return
	end
	local grid = cached(key)
	if grid and grid.price then
		return
	end
	job = {
		key = key,
		run = coroutine.create(function()
			local g = Corridors.Grid(key)
			if g then
				coroutine.yield()
				Walk.Prices(g, coroutine.yield)
			end
		end),
	}
	if not scheduled then
		scheduled = true
		C_Timer.After(0, step)
	end
end

-- The grid of a key with its prices, finishing its preparation now when it is in progress or not started.
local function ready(key)
	local j = job
	if j and j.key == key then
		job = nil
		while coroutine.status(j.run) ~= "dead" do
			local ok, err = coroutine.resume(j.run)
			if not ok then
				ns:Debug("corridors: " .. tostring(err))
				break
			end
		end
	end
	local grid = Corridors.Grid(key)
	if grid then
		Walk.Prices(grid)
	end
	return grid
end

local function round(v)
	return math.floor(math.max(0, math.min(1, v)) * 10000 + 0.5) / 10000
end

-- The bends of the leg from (ax, ay) to (bx, by) on plan floor `index`, found now: bends in plan space ({ { x, y }, ... },
-- rounded like the plan's points; empty: the straight line is clear), or nil and why ("grid": no grid for the floor,
-- "off", "none", "limit": Model/Walk.lua).
function Corridors.Leg(plan, index, ax, ay, bx, by)
	local key, align = Corridors.KeyFor(plan, index)
	local grid = key and ready(key)
	if not grid then
		return nil, "grid"
	end
	local gx, gy = ns.MinimapArt.ToMap(align, ax, ay)
	local hx, hy = ns.MinimapArt.ToMap(align, bx, by)
	local bends, why, st = Walk.Path(grid, gx, gy, hx, hy)
	stats.legs = stats.legs + 1
	stats.maxExpanded = math.max(stats.maxExpanded, st.expanded)
	if bends then
		for i, b in ipairs(bends) do
			local x, y = ns.MinimapArt.FromMap(align, b[1], b[2])
			bends[i] = { round(x), round(y) }
		end
	end
	return bends, why
end

-- Is the straight line from (ax, ay) to (bx, by) on plan floor `index` walkable? (false without a grid)
function Corridors.Clear(plan, index, ax, ay, bx, by)
	local key, align = Corridors.KeyFor(plan, index)
	local grid = key and Corridors.Grid(key)
	if not grid then
		return false
	end
	local gx, gy = ns.MinimapArt.ToMap(align, ax, ay)
	local hx, hy = ns.MinimapArt.ToMap(align, bx, by)
	gx, gy, hx, hy = gx * grid.w, gy * grid.h, hx * grid.w, hy * grid.h
	return Walk.Open(grid, math.floor(gx), math.floor(gy)) and Walk.Clear(grid, gx, gy, hx, hy) or false
end

-- The key of the floor being prepared, or nil (tests).
function Corridors.Preparing()
	return job and job.key or nil
end

-- Is the grid of `key` decoded and prepared? (tests)
function Corridors.Ready(key)
	for _, e in ipairs(cache) do
		if e[1] == key then
			return e[2].price ~= nil
		end
	end
	return false
end

-- Every recommended plan's floors with and without a grid, for /dp debug: counts and the floors without.
function Corridors.Summary()
	local with, without = 0, {}
	for _, plan in ipairs(ns.Bundled.All()) do
		for i, f in ipairs(plan.floors) do
			if not ns.Floors.IsOutside(f) then
				if Corridors.Has(plan, i) then
					with = with + 1
				else
					without[#without + 1] = ns.Names.Instance(plan.instance) .. " " .. i
				end
			end
		end
	end
	local grids = 0
	for _ in pairs(ns.WalkData or {}) do
		grids = grids + 1
	end
	return { floors = with, grids = grids, without = without }
end

-- Drops the decoded grids and the preparation in progress (tests, and the measurement in tools/walk_timing.lua).
function Corridors.Reset()
	cache, job = {}, nil
end
